"""R2 single offline HTML + reusable local source. R1 fallback remains outside this ZIP."""
from pathlib import Path
import json,zipfile,hashlib
ROOT=Path(__file__).resolve().parents[2];BASE=ROOT/'previews/layla';out=ROOT/'deliverables/Layla-Animation-Preview-R2-Source.zip'
v=json.loads((BASE/'verification-r2.json').read_text());assert v['revision']=='layla-workshop-r2' and not v['gameIntegration'] and not v['differences'] and v['focused']['fail']==0 and v['browserGroups']==51
for p,h in v['assets'].items():assert hashlib.sha256((ROOT/p).read_bytes()).hexdigest()==h,p
package={'name':'layla-energy-effects-workshop','version':'0.2.0','type':'module','private':True,'scripts':{'build':'node scripts/layla/build-preview.mjs','test':'node --test tests/layla-preview.test.js tests/layla-effects.test.js','test:browser':'node tests/browser-layla-preview.mjs && node tests/browser-layla-effects.mjs'},'dependencies':{'three':'0.186.1'},'devDependencies':{'@sparticuz/chromium':'153.0.0','playwright-core':'1.64.1','vite':'7.3.7'}}
lock=json.loads((ROOT/'package-lock.json').read_text());lock['name']=package['name'];lock['version']=package['version'];lock['packages']['']['name']=package['name'];lock['packages']['']['version']=package['version']
names=['index.html','viewer.js','simulation.js','effects.js','comparison.js','style.css','settings.json','research.json','asset-manifest.json','assets/layla-rework.glb','LICENSE-THREE.txt','README.md','Layla-Animation-Preview.html','preservation.json','effects-preservation.json','baseline-test-status.json','unit-r2-results.txt','full-unit-r2-results.txt','browser-results.json','browser-effects-results.json','verification-r2.json']
for n in ['REVIEW-REPORT-R2.md','fresh-directory-r2.json','fresh-unit-r2-results.txt','browser-r2-isolated-regression.json','browser-r2-isolated-effects.json']:
 if(BASE/n).exists():names.append(n)
files=[BASE/n for n in names]+[ROOT/p for p in ['assets/source_blender/layla-rework-preview.blend','scripts/layla/author-model.py','scripts/layla/build-preview.mjs','scripts/layla/serve-preview.py','scripts/layla/audit-effects.mjs','scripts/layla/package-effects.py','docs/LAYLA_PREVIEW_SPEC.md','tests/layla-preview.test.js','tests/layla-effects.test.js','tests/browser-layla-preview.mjs','tests/browser-layla-effects.mjs','tests/helpers/offline-browser.mjs']]
with zipfile.ZipFile(out,'w',zipfile.ZIP_DEFLATED,compresslevel=8)as z:
 for p in sorted(set(files)):
  path=p.relative_to(ROOT);assert not any(x in path.parts for x in ['node_modules','.git','.cache','artifacts','references','revisions','deliverables']);z.write(p,path.as_posix())
 z.writestr('package.json',json.dumps(package,indent=2)+'\n');z.writestr('package-lock.json',json.dumps(lock,indent=2)+'\n')
 z.writestr('README.md','# Layla Energy Gunner — R2 effects review only\n\nOpen `previews/layla/Layla-Animation-Preview.html` alone in a modern WebGL2 browser. No server/install/adjacent assets/internet needed for viewing. Click Four-attack comparison; inspect Release/flight, Initial impact, Mark state, Mark trigger/stun, and Play all at normal/slow speed. Shared full-range scale compares the same camera/world scale. In the workshop choose Ultimate and Near+mid+far line for the full48u beam. Range/width/flash/glow are independent provisional values, not verified in-game measurements.\n\nSee `previews/layla/README.md`, `docs/LAYLA_PREVIEW_SPEC.md` and `previews/layla/REVIEW-REPORT-R2.md` for controls, provenance, original GLB/Blender source, source clips versus editable presentation clocks, verification and limitations.\n\nTo edit/rebuild: `npm ci && npm run build`. This installs build/test dependencies; internet is required only for initial dependency installation, not for using the delivered HTML. `npm test` runs32 focused tests. `npm run test:browser` runs both offline suites. Full repository evidence is827/828 with the unchanged pre-existing absent-Franco-Plan-A-download failure. The preservation audit needs the original full workspace and is not expected to run in this smaller package. Blender/bpy4.2 is optional for reauthoring, not viewing/building.\n\nModel, rig and source clips are preserved byte-for-byte. All effects are original procedural local assets; no runtime texture dependencies, ripped assets, supplied reference screenshots, Git, dependency folders, captures or duplicate R1/Franco/full-game builds are included. R1 is retained separately in the full workspace. No game integration, hero approval or next-hero work is authorized. STOP for feedback.\n')
with zipfile.ZipFile(out)as z:
 assert z.testzip()is None;assert len(z.namelist())==len(set(z.namelist()));assert z.read('previews/layla/Layla-Animation-Preview.html')==(BASE/'Layla-Animation-Preview.html').read_bytes()
 print(out,out.stat().st_size,'bytes;',len(z.namelist()),'entries; CRC/HTML equality pass')
